def get_store_seo(business_slug, category_slug=None, default_name=''):
    """
    Returns SEO title, meta description, h1, badge, and intro content
    for a store vertical or specific category page.
    """
    if category_slug and category_slug in CATEGORY_SEO:
        return CATEGORY_SEO[category_slug]

    if business_slug and business_slug in STORE_VERTICAL_SEO:
        return STORE_VERTICAL_SEO[business_slug]

    # Fallback if unmapped
    name = default_name or (category_slug or business_slug or 'Store').replace('-', ' ').title()
    return {
        'title': f'{name} | Sathik Groups',
        'meta_description': f'Explore {name} products at Sathik Groups in Red Hills, Chennai. Wholesale hardware, plumbing, and sanitaryware supply.',
        'h1': f'{name} in Red Hills, Chennai',
        'badge': f'{name} Store',
        'intro': f'Browse quality {name} products available at Sathik Groups in Red Hills, Chennai. Visit our <a href="/locations/red-hills/" style="color: var(--primary-600); font-weight: 600; text-decoration: underline;">Red Hills store</a>.'
    }
